private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int b = bb.get(i) & 0xFF;
    if (b < 0x80) {
        sb.append((char) b);
        return i + 1;
    } else if (b < 0xC0) {
        // error: illegal tail byte
        return -1;
    } else if (b < 0xE0) {
        int bytesLeft = 2;
        int codepoint = b & 0x1F;
        while (bytesLeft > 0) {
            i++;
            b = bb.get(i) & 0xFF;
            if (b < 0x80 || b > 0xBF) {
                // error: illegal tail byte
                return -1;
            }
            codepoint = (codepoint << 6) | (b & 0x3F);
            bytesLeft--;
        }
        sb.append((char) codepoint);
        return i + 1;
    } else if (b < 0xF0) {
        int bytesLeft = 3;
        int codepoint = b & 0x0F;
        while (bytesLeft > 0) {
            i++;
            b = bb.get(i) & 0xFF;
            if (b < 0x80 || b > 0xBF) {
                // error: illegal tail byte
                return -1;
            }
            codepoint = (codepoint << 6) | (b & 0x3F);
            bytesLeft--;
        }
        sb.append((char) codepoint);
        return i + 1;
    } else {
        // error: illegal tail byte
        return -1;
    }
}
